"use client";

import { useState, useMemo, useEffect } from "react";
import {
  Box, Button, Chip, Dialog, DialogContent, DialogTitle, Divider,
  IconButton, Paper, Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, Typography, InputAdornment, TextField,
} from "@mui/material";
import {
  AccountBalanceWallet, ArrowDownward, ArrowUpward, Close,
  CreditCard, Search, Wallet,
} from "@mui/icons-material";
import { cellSx, headCellSx, formatIDR, searchInputSx, tipeLabels } from "@/lib/theme-shared";
import { getAccountsAction } from "@/features/account/actions";
import { getLatestRatesAction } from "@/features/exchange/actions";

// ─── Types ────────────────────────────────────────────────────────────────────
type CashflowAccount = {
  id: string;
  nama: string;
  tipe: "BANK" | "CASH" | "E_WALLET";
  currency: string;
  saldo: number;
  updatedAt: string;
  aktif: boolean;
};

type MutasiEntry = {
  tanggal: string;
  arah: "CREDIT" | "DEBIT";
  nominal: number;
  kategori: string;
  catatan: string;
};

// ─── Helpers ─────────────────────────────────────────────────────────────────
const tipeConfig: Record<string, { color: string; bg: string; icon: React.ReactNode }> = {
  BANK: { color: "#818cf8", bg: "rgba(129,140,248,0.12)", icon: <CreditCard sx={{ fontSize: 15 }} /> },
  CASH: { color: "#94a3b8", bg: "rgba(148,163,184,0.12)", icon: <AccountBalanceWallet sx={{ fontSize: 15 }} /> },
  E_WALLET: { color: "#ec4899", bg: "rgba(236,72,153,0.12)", icon: <Wallet sx={{ fontSize: 15 }} /> },
};

const formatCurrency = (val: number, currency: string) => {
  try {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: currency,
      maximumFractionDigits: currency === 'IDR' ? 0 : 2,
    }).format(val);
  } catch {
    return `${currency} ${val.toLocaleString("id-ID")}`;
  }
};
// tipeLabels and searchInputSx are imported from @/lib/theme-shared

// ─── Component ────────────────────────────────────────────────────────────────
export default function CashflowPage() {
  const [accounts, setAccounts] = useState<CashflowAccount[]>([]);
  const [mutasi, setMutasi] = useState<Record<string, MutasiEntry[]>>({});
  const [selected, setSelected] = useState<CashflowAccount | null>(null);
  const [search, setSearch] = useState("");
  const [mutasiSearch, setMutasiSearch] = useState("");
  const [loading, setLoading] = useState(true);
  const [ratesMap, setRatesMap] = useState<Record<string, number>>({ 'USD': 1, 'IDR': 17364 });

  const fetchData = async () => {
    try {
      const ratesRes = await getLatestRatesAction();
      if (ratesRes.success && Array.isArray(ratesRes.data)) {
        const map: Record<string, number> = { 'USD': 1 };
        ratesRes.data.forEach((r: any) => { if (r.rate) map[r.code] = r.rate; });
        setRatesMap(prev => ({ ...prev, ...map }));
      }

      const res = await getAccountsAction({ bucket: 'CASHFLOW', includeLedger: true });
      if (res.success && res.data) {
        const mappedAccounts = (res.data as any[]).map((acc: any) => ({
          id: String(acc.id),
          nama: acc.name,
          tipe: acc.type,
          currency: acc.currency,
          saldo: Number(acc.balance),
          updatedAt: acc.updatedAt,
          aktif: acc.isActive,
        }));

        const mappedMutasi: Record<string, MutasiEntry[]> = {};
        (res.data as any[]).forEach((acc: any) => {
          mappedMutasi[String(acc.id)] = (acc.ledgerEntries || []).map((entry: any) => ({
            tanggal: entry.date,
            arah: entry.direction,
            nominal: Number(entry.amount),
            kategori: entry.refType || "Lainnya",
            catatan: entry.note || "",
          }));
        });

        setAccounts(mappedAccounts);
        setMutasi(mappedMutasi);
      }
    } catch (err) {
      console.error("Failed to fetch cashflow accounts", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    const handleRefresh = () => {
      fetchData();
    };

    window.addEventListener("refresh-data", handleRefresh);
    return () => {
      window.removeEventListener("refresh-data", handleRefresh);
    };
  }, []);

  const toIDR = (amt: number, currency: string) => {
    const idrRate = ratesMap['IDR'] || 17364;
    const rate = ratesMap[currency] || (currency === "USD" ? 1 : null);
    if (!rate) return amt;
    return (amt / rate) * idrRate;
  };

  const totalSaldo = useMemo(() => 
    accounts.filter((a) => a.aktif).reduce((s, a) => s + toIDR(a.saldo, a.currency), 0),
  [accounts, ratesMap]);

  // Credit/debit this month from selected
  const selectedMutasi = selected ? (mutasi[selected.id] ?? []) : [];
  const filteredMutasi = useMemo(() =>
    selectedMutasi.filter((m) =>
      [m.kategori, m.catatan, m.arah].join(" ").toLowerCase().includes(mutasiSearch.toLowerCase())
    ), [selectedMutasi, mutasiSearch]);

  const creditTotal = selectedMutasi.filter((m) => m.arah === "CREDIT").reduce((s, m) => s + m.nominal, 0);
  const debitTotal = selectedMutasi.filter((m) => m.arah === "DEBIT").reduce((s, m) => s + m.nominal, 0);

  const filteredAccounts = useMemo(() =>
    accounts.filter((a) =>
      [a.id, a.nama, a.tipe].join(" ").toLowerCase().includes(search.toLowerCase())
    ), [accounts, search]);

  const byTipe = useMemo(() => {
    const map: Record<string, number> = {
      BANK: 0,
      CASH: 0,
      E_WALLET: 0,
    };
    accounts.filter((a) => a.aktif).forEach((a) => { 
      map[a.tipe] = (map[a.tipe] ?? 0) + toIDR(a.saldo, a.currency); 
    });
    return map;
  }, [accounts, ratesMap]);

  return (
    <Box sx={{ p: { xs: 3, md: 4 }, minHeight: "100vh" }}>
      {/* Header */}
      <Box sx={{ mb: 4 }}>
        <Box sx={{ display: "flex", alignItems: "center", gap: 1.5, mb: 0.5 }}>
          <Box sx={{ width: 36, height: 36, borderRadius: "10px", backgroundColor: "rgba(34,197,94,0.12)", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <AccountBalanceWallet sx={{ fontSize: 18, color: "#22c55e" }} />
          </Box>
          <Typography variant="h5" sx={{ fontWeight: 700, color: "#f1f5f9", fontSize: "1.25rem" }}>Cashflow</Typography>
        </Box>
        <Typography variant="body2" sx={{ color: "#64748b", ml: "52px" }}>Saldo aktif harian — bank, cash, dan e-wallet</Typography>
      </Box>

      {/* Summary Cards */}
      <Box sx={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 2, mb: 3 }}>
        <Paper elevation={0} sx={{ p: 2.5, borderRadius: "14px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)", gridColumn: "span 1" }}>
          <Typography sx={{ fontSize: "0.7rem", color: "#64748b", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.06em", mb: 1 }}>Total Cashflow</Typography>
          <Typography sx={{ fontSize: "1.375rem", fontWeight: 700, color: "#22c55e", lineHeight: 1.2 }}>{formatIDR(totalSaldo)}</Typography>
          <Typography sx={{ fontSize: "0.75rem", color: "#475569", mt: 0.5 }}>{accounts.filter((a) => a.aktif).length} akun aktif</Typography>
        </Paper>
        {Object.entries(byTipe).map(([tipe, saldo]) => {
          const cfg = tipeConfig[tipe];
          return (
            <Paper key={tipe} elevation={0} sx={{ p: 2.5, borderRadius: "14px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)" }}>
              <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 1 }}>
                <Box sx={{ width: 22, height: 22, borderRadius: "6px", backgroundColor: cfg.bg, display: "flex", alignItems: "center", justifyContent: "center", color: cfg.color }}>
                  {cfg.icon}
                </Box>
                <Typography sx={{ fontSize: "0.7rem", color: "#64748b", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.06em" }}>{tipe.replace("_", "-")}</Typography>
              </Box>
              <Typography sx={{ fontSize: "1.125rem", fontWeight: 700, color: cfg.color, lineHeight: 1.2 }}>{formatIDR(saldo)}</Typography>
              <Typography sx={{ fontSize: "0.75rem", color: "#475569", mt: 0.5 }}>
                {accounts.filter((a) => a.tipe === tipe && a.aktif).length} akun
              </Typography>
            </Paper>
          );
        })}
      </Box>

      {/* Accounts Table */}
      <Paper elevation={0} sx={{ borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)", overflow: "hidden" }}>
        <Box sx={{ px: 3, py: 2, borderBottom: "1px solid rgba(255,255,255,0.05)", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 2, flexWrap: "wrap" }}>
          <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
            <Typography sx={{ fontWeight: 700, color: "#e2e8f0", fontSize: "0.9375rem", whiteSpace: "nowrap" }}>Daftar Akun</Typography>
            <TextField size="small" placeholder="Cari akun..." value={search} onChange={(e) => setSearch(e.target.value)}
              sx={{ width: 200, ...searchInputSx }}
              InputProps={{ startAdornment: <InputAdornment position="start"><Search /></InputAdornment> }} />
          </Box>
          <Typography sx={{ fontSize: "0.75rem", color: "#475569" }}>Klik baris untuk lihat riwayat mutasi</Typography>
        </Box>

        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                {["Nama Akun", "Tipe", "Mata Uang", "Saldo", "Terakhir Update", ""].map((h) => (
                  <TableCell key={h} sx={headCellSx}>{h}</TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredAccounts.length === 0 ? (
                <TableRow><TableCell colSpan={6} sx={{ ...cellSx, textAlign: "center", py: 5, color: "#475569" }}>Tidak ada akun ditemukan.</TableCell></TableRow>
              ) : filteredAccounts.map((acc, i) => {
                const cfg = tipeConfig[acc.tipe];
                return (
                  <TableRow key={acc.id} onClick={() => { setSelected(acc); setMutasiSearch(""); }}
                    sx={{ backgroundColor: i % 2 === 0 ? "transparent" : "rgba(255,255,255,0.015)", "&:hover": { backgroundColor: "rgba(34,197,94,0.05)", cursor: "pointer" }, transition: "background-color 0.15s", opacity: acc.aktif ? 1 : 0.5 }}>
                    <TableCell sx={{ ...cellSx, fontWeight: 600, color: "#e2e8f0" }}>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
                        <Box sx={{ width: 32, height: 32, borderRadius: "9px", backgroundColor: cfg.bg, display: "flex", alignItems: "center", justifyContent: "center", color: cfg.color }}>
                          {cfg.icon}
                        </Box>
                        {acc.nama}
                      </Box>
                    </TableCell>
                    <TableCell sx={cellSx}>
                      <Chip label={tipeLabels[acc.tipe] || acc.tipe} size="small"
                        sx={{ fontSize: "0.6875rem", height: 22, fontWeight: 600, borderRadius: "6px", backgroundColor: cfg.bg, color: cfg.color, border: `1px solid ${cfg.color}30` }} />
                    </TableCell>
                    <TableCell sx={cellSx}>
                      <Chip label={acc.currency} size="small"
                        sx={{ fontSize: "0.6875rem", height: 22, fontWeight: 700, borderRadius: "6px", backgroundColor: "rgba(99,102,241,0.15)", color: "#a5b4fc" }} />
                    </TableCell>
                    <TableCell sx={{ ...cellSx, fontWeight: 700, color: "#22c55e", whiteSpace: "nowrap" }}>{formatCurrency(acc.saldo, acc.currency)}</TableCell>
                    <TableCell sx={{ ...cellSx, color: "#475569", fontSize: "0.75rem" }}>
                      {new Date(acc.updatedAt).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" })}
                    </TableCell>
                    <TableCell sx={cellSx}>
                      <Typography sx={{ fontSize: "0.75rem", color: "#6366f1", fontWeight: 600 }}>
                        {(mutasi[acc.id] ?? []).length} mutasi →
                      </Typography>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      {/* Mutasi Dialog */}
      <Dialog open={Boolean(selected)} onClose={() => setSelected(null)} maxWidth="md" fullWidth
        PaperProps={{ elevation: 0, sx: { backgroundColor: "#1e293b", border: "1px solid rgba(255,255,255,0.08)", borderRadius: "16px" } }}>
        {selected && (() => {
          const cfg = tipeConfig[selected.tipe];
          return (
            <>
              <DialogTitle sx={{ pb: 0 }}>
                <Box sx={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between" }}>
                  <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
                    <Box sx={{ width: 40, height: 40, borderRadius: "11px", backgroundColor: cfg.bg, display: "flex", alignItems: "center", justifyContent: "center", color: cfg.color, flexShrink: 0 }}>
                      {cfg.icon}
                    </Box>
                    <Box>
                      <Typography sx={{ fontWeight: 700, color: "#f1f5f9", fontSize: "1.0625rem" }}>{selected.nama}</Typography>
                      <Typography sx={{ fontSize: "0.75rem", color: "#64748b" }}>Riwayat mutasi akun</Typography>
                    </Box>
                  </Box>
                  <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                    <Box sx={{ textAlign: "right" }}>
                      <Typography sx={{ fontSize: "0.7rem", color: "#64748b", mb: 0.25 }}>Saldo</Typography>
                      <Typography sx={{ fontWeight: 800, color: "#22c55e", fontSize: "1.125rem" }}>{formatCurrency(selected.saldo, selected.currency)}</Typography>
                    </Box>
                    <IconButton size="small" onClick={() => setSelected(null)} sx={{ color: "#64748b", "&:hover": { color: "#94a3b8" } }}><Close fontSize="small" /></IconButton>
                  </Box>
                </Box>
                {/* Mini stats */}
                <Box sx={{ display: "flex", gap: 2, mt: 2, mb: 0 }}>
                  {[
                    { label: "Total Masuk", value: formatCurrency(creditTotal, selected.currency), color: "#22c55e", icon: <ArrowUpward sx={{ fontSize: 11 }} /> },
                    { label: "Total Keluar", value: formatCurrency(debitTotal, selected.currency), color: "#ef4444", icon: <ArrowDownward sx={{ fontSize: 11 }} /> },
                    { label: "Transaksi", value: `${selectedMutasi.length}x`, color: "#94a3b8", icon: null },
                  ].map((s) => (
                    <Box key={s.label} sx={{ flex: 1, px: 1.5, py: 1, borderRadius: "10px", backgroundColor: "rgba(0,0,0,0.2)", border: "1px solid rgba(255,255,255,0.05)" }}>
                      <Typography sx={{ fontSize: "0.65rem", color: "#64748b", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.06em", mb: 0.25 }}>{s.label}</Typography>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 0.5, color: s.color }}>
                        {s.icon}
                        <Typography sx={{ fontSize: "0.875rem", fontWeight: 700, color: s.color }}>{s.value}</Typography>
                      </Box>
                    </Box>
                  ))}
                </Box>
              </DialogTitle>
              <Divider sx={{ borderColor: "rgba(255,255,255,0.06)", mt: 2 }} />
              <Box sx={{ px: 3, py: 1.5, borderBottom: "1px solid rgba(255,255,255,0.05)" }}>
                <TextField size="small" placeholder="Cari mutasi..." value={mutasiSearch} onChange={(e) => setMutasiSearch(e.target.value)}
                  sx={{ width: "100%", ...searchInputSx }}
                  InputProps={{ startAdornment: <InputAdornment position="start"><Search /></InputAdornment> }} />
              </Box>
              <DialogContent sx={{ p: 0, maxHeight: 400, overflow: "auto" }}>
                <TableContainer>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        {["Tanggal", "Perubahan", "Kategori", "Catatan"].map((h) => (
                          <TableCell key={h} sx={{ ...headCellSx, backgroundColor: "#1a2942" }}>{h}</TableCell>
                        ))}
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {filteredMutasi.length === 0 ? (
                        <TableRow><TableCell colSpan={4} sx={{ ...cellSx, textAlign: "center", py: 4, color: "#475569" }}>Tidak ada mutasi ditemukan.</TableCell></TableRow>
                      ) : filteredMutasi.map((entry, i) => (
                        <TableRow key={i} sx={{ "&:hover": { backgroundColor: "rgba(99,102,241,0.05)" } }}>
                          <TableCell sx={{ ...cellSx, color: "#475569", fontSize: "0.75rem", whiteSpace: "nowrap" }}>
                            {new Date(entry.tanggal).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" })}
                          </TableCell>
                          <TableCell sx={cellSx}>
                            <Box sx={{ display: "flex", alignItems: "center", gap: 0.75 }}>
                              <Box sx={{ width: 20, height: 20, borderRadius: "6px", backgroundColor: entry.arah === "CREDIT" ? "rgba(34,197,94,0.12)" : "rgba(239,68,68,0.12)", display: "flex", alignItems: "center", justifyContent: "center" }}>
                                {entry.arah === "CREDIT" ? <ArrowUpward sx={{ fontSize: 10, color: "#22c55e" }} /> : <ArrowDownward sx={{ fontSize: 10, color: "#ef4444" }} />}
                              </Box>
                              <Typography sx={{ fontSize: "0.8125rem", fontWeight: 700, color: entry.arah === "CREDIT" ? "#22c55e" : "#ef4444", whiteSpace: "nowrap" }}>
                                {entry.arah === "CREDIT" ? "+" : "-"}{formatCurrency(entry.nominal, selected.currency)}
                              </Typography>
                            </Box>
                          </TableCell>
                          <TableCell sx={cellSx}>
                            <Chip label={entry.kategori} size="small"
                              sx={{ fontSize: "0.6rem", height: 18, fontWeight: 500, borderRadius: "5px", backgroundColor: "rgba(71,85,105,0.4)", color: "#94a3b8" }} />
                          </TableCell>
                          <TableCell sx={{ ...cellSx, color: "#64748b" }}>{entry.catatan}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              </DialogContent>
            </>
          );
        })()}
      </Dialog>
    </Box>
  );
}